PRODUCTION_SOURCE = '"""\nOLA-036\nOracle Live Acquisition Lineage Cycle Bridge\n\nCanonical cycle-boundary integration above OLA-035.\n\nPurpose:\n- accept one completed canonical live acquisition market cohort\n- bind every observation in the cohort to one exact cycle observed-at time\n- preserve canonical acquisition batch identity across the cohort\n- route the complete cohort atomically through OLA-035\n- return one immutable cycle receipt binding acquisition-cycle identity to\n  exact market-state dwell/change lineage advancement\n\nThis boundary does not acquire data itself and owns no persistence,\nintelligence interpretation, scoring, alerting, Q Series handoff,\nauthorization, or execution.\n\nOracle remains permanently read-only.\n"""\n\nfrom __future__ import annotations\n\nfrom dataclasses import dataclass\nfrom datetime import datetime, timezone\nfrom hashlib import sha256\nimport json\nfrom typing import Any, Iterable\n\nfrom .oracle_atomic_market_lineage_batch_router import (\n    AtomicMarketLineageBatchContractError,\n    AtomicMarketLineageBatchFrame,\n    AtomicMarketLineageBatchInvariantError,\n    AtomicMarketLineageBatchReceipt,\n    OracleAtomicMarketLineageBatchRouter,\n)\nfrom .oracle_live_read_only_acquisition_runtime import (\n    CanonicalObservation,\n)\n\n\nSCHEMA_VERSION = "OLA-036"\nENGINE_ID = "OLA-036"\nRECEIPT_TYPE = "oracle_live_acquisition_lineage_cycle_receipt"\n\nREAD_ONLY = True\nEXECUTION_ALLOWED = False\nEXECUTION_ADAPTER_RESOLVED = False\nEXECUTION_ADAPTER_INVOKED = False\nTRADE_AUTHORIZATION_ALLOWED = False\nORDER_PLACEMENT_ALLOWED = False\nFUNDS_MOVED = False\nPORTFOLIO_MUTATED = False\n\n\nclass LiveAcquisitionLineageCycleContractError(ValueError):\n    """Raised when OLA-036 cycle input is malformed."""\n\n\nclass LiveAcquisitionLineageCycleInvariantError(RuntimeError):\n    """Raised when permanent OLA-036 invariants are violated."""\n\n\ndef _require_utc_datetime(\n    value: Any,\n    field_name: str,\n) -> datetime:\n    if not isinstance(value, datetime):\n        raise LiveAcquisitionLineageCycleContractError(\n            f"{field_name} must be a datetime"\n        )\n    if value.tzinfo is None:\n        raise LiveAcquisitionLineageCycleContractError(\n            f"{field_name} must be timezone-aware"\n        )\n\n    return value.astimezone(timezone.utc)\n\n\ndef _stable_hash(value: Any) -> str:\n    encoded = json.dumps(\n        value,\n        sort_keys=True,\n        separators=(",", ":"),\n        ensure_ascii=False,\n        allow_nan=False,\n    ).encode("utf-8")\n    return sha256(encoded).hexdigest()\n\n\n@dataclass(frozen=True, slots=True)\nclass LiveAcquisitionLineageCycleReceipt:\n    schema_version: str\n    engine_id: str\n    receipt_type: str\n    acquisition_batch_id: str\n    cycle_observed_at: str\n    cohort_observation_count: int\n    cohort_market_count: int\n    transition_count: int\n    ledger_market_count_before: int\n    ledger_record_count_before: int\n    ledger_market_count_after: int\n    ledger_record_count_after: int\n    lineage_batch_receipt: AtomicMarketLineageBatchReceipt\n    read_only: bool\n    execution_allowed: bool\n    execution_adapter_resolved: bool\n    execution_adapter_invoked: bool\n    trade_authorization_allowed: bool\n    order_placement_allowed: bool\n    funds_moved: bool\n    portfolio_mutated: bool\n    cycle_receipt_hash: str\n\n    def assert_invariants(self) -> None:\n        if self.schema_version != SCHEMA_VERSION:\n            raise LiveAcquisitionLineageCycleInvariantError(\n                "schema version invariant violated"\n            )\n        if self.engine_id != ENGINE_ID:\n            raise LiveAcquisitionLineageCycleInvariantError(\n                "engine identity invariant violated"\n            )\n        if self.receipt_type != RECEIPT_TYPE:\n            raise LiveAcquisitionLineageCycleInvariantError(\n                "receipt type invariant violated"\n            )\n        if self.cohort_observation_count <= 0:\n            raise LiveAcquisitionLineageCycleInvariantError(\n                "cohort observation count must be positive"\n            )\n        if self.cohort_market_count <= 0:\n            raise LiveAcquisitionLineageCycleInvariantError(\n                "cohort market count must be positive"\n            )\n        if (\n            self.cohort_observation_count\n            != self.lineage_batch_receipt.batch_frame_count\n        ):\n            raise LiveAcquisitionLineageCycleInvariantError(\n                "cycle and lineage batch frame counts diverged"\n            )\n        if (\n            self.cohort_market_count\n            != self.lineage_batch_receipt.batch_market_count\n        ):\n            raise LiveAcquisitionLineageCycleInvariantError(\n                "cycle and lineage batch market counts diverged"\n            )\n        if (\n            self.transition_count\n            != self.lineage_batch_receipt.transition_count\n        ):\n            raise LiveAcquisitionLineageCycleInvariantError(\n                "cycle transition count diverged"\n            )\n\n        authority = (\n            self.read_only,\n            self.execution_allowed,\n            self.execution_adapter_resolved,\n            self.execution_adapter_invoked,\n            self.trade_authorization_allowed,\n            self.order_placement_allowed,\n            self.funds_moved,\n            self.portfolio_mutated,\n        )\n\n        if authority != (\n            True,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n            False,\n        ):\n            raise LiveAcquisitionLineageCycleInvariantError(\n                "OLA-036 read-only authority invariants violated"\n            )\n\n\nclass OracleLiveAcquisitionLineageCycleBridge:\n    read_only = True\n    execution_allowed = False\n\n    def __init__(\n        self,\n        *,\n        batch_router: OracleAtomicMarketLineageBatchRouter | None = None,\n    ) -> None:\n        self._batch_router = (\n            batch_router\n            if batch_router is not None\n            else OracleAtomicMarketLineageBatchRouter()\n        )\n\n        if not isinstance(\n            self._batch_router,\n            OracleAtomicMarketLineageBatchRouter,\n        ):\n            raise LiveAcquisitionLineageCycleContractError(\n                "batch_router must be an OLA-035 "\n                "OracleAtomicMarketLineageBatchRouter"\n            )\n\n    @property\n    def batch_router(self) -> OracleAtomicMarketLineageBatchRouter:\n        return self._batch_router\n\n    def advance_cycle(\n        self,\n        *,\n        observations: Iterable[CanonicalObservation],\n        cycle_observed_at: datetime,\n    ) -> LiveAcquisitionLineageCycleReceipt:\n        normalized_observations = tuple(observations)\n\n        if not normalized_observations:\n            raise LiveAcquisitionLineageCycleContractError(\n                "cycle must contain at least one canonical observation"\n            )\n\n        cycle_time = _require_utc_datetime(\n            cycle_observed_at,\n            "cycle_observed_at",\n        )\n\n        acquisition_batch_ids: set[str] = set()\n\n        for observation in normalized_observations:\n            if not isinstance(observation, CanonicalObservation):\n                raise LiveAcquisitionLineageCycleContractError(\n                    "cycle observations must be canonical observations"\n                )\n            if observation.observation_type != "market_snapshot":\n                raise LiveAcquisitionLineageCycleContractError(\n                    "cycle accepts only market_snapshot observations"\n                )\n\n            acquisition_batch_id = observation.acquisition_batch_id\n\n            if not isinstance(acquisition_batch_id, str):\n                raise LiveAcquisitionLineageCycleContractError(\n                    "acquisition_batch_id must be a string"\n                )\n\n            normalized_batch_id = acquisition_batch_id.strip()\n\n            if not normalized_batch_id:\n                raise LiveAcquisitionLineageCycleContractError(\n                    "acquisition_batch_id must not be empty"\n                )\n\n            acquisition_batch_ids.add(normalized_batch_id)\n\n        if len(acquisition_batch_ids) != 1:\n            raise LiveAcquisitionLineageCycleContractError(\n                "all cycle observations must share one acquisition_batch_id"\n            )\n\n        acquisition_batch_id = next(iter(acquisition_batch_ids))\n\n        frames = tuple(\n            AtomicMarketLineageBatchFrame(\n                observation=observation,\n                frame_observed_at=cycle_time,\n            )\n            for observation in normalized_observations\n        )\n\n        try:\n            batch_receipt = self._batch_router.route(\n                frames=frames\n            )\n        except AtomicMarketLineageBatchContractError as exc:\n            raise LiveAcquisitionLineageCycleContractError(\n                f"OLA-035 lineage batch rejected cycle: {exc}"\n            ) from exc\n        except AtomicMarketLineageBatchInvariantError as exc:\n            raise LiveAcquisitionLineageCycleInvariantError(\n                f"OLA-035 lineage batch invariant failed: {exc}"\n            ) from exc\n\n        payload = {\n            "schema_version": SCHEMA_VERSION,\n            "engine_id": ENGINE_ID,\n            "receipt_type": RECEIPT_TYPE,\n            "acquisition_batch_id": acquisition_batch_id,\n            "cycle_observed_at": cycle_time.isoformat(),\n            "cohort_observation_count": len(normalized_observations),\n            "cohort_market_count": batch_receipt.batch_market_count,\n            "transition_count": batch_receipt.transition_count,\n            "ledger_market_count_before": (\n                batch_receipt.ledger_market_count_before\n            ),\n            "ledger_record_count_before": (\n                batch_receipt.ledger_record_count_before\n            ),\n            "ledger_market_count_after": (\n                batch_receipt.ledger_market_count_after\n            ),\n            "ledger_record_count_after": (\n                batch_receipt.ledger_record_count_after\n            ),\n            "lineage_batch_receipt": {\n                "schema_version": batch_receipt.schema_version,\n                "engine_id": batch_receipt.engine_id,\n                "status": batch_receipt.status,\n                "batch_frame_count": batch_receipt.batch_frame_count,\n                "batch_market_count": batch_receipt.batch_market_count,\n                "transition_count": batch_receipt.transition_count,\n                "receipt_hashes": [\n                    receipt.receipt_hash\n                    for receipt in batch_receipt.receipts\n                ],\n            },\n            "read_only": READ_ONLY,\n            "execution_allowed": EXECUTION_ALLOWED,\n            "execution_adapter_resolved": EXECUTION_ADAPTER_RESOLVED,\n            "execution_adapter_invoked": EXECUTION_ADAPTER_INVOKED,\n            "trade_authorization_allowed": TRADE_AUTHORIZATION_ALLOWED,\n            "order_placement_allowed": ORDER_PLACEMENT_ALLOWED,\n            "funds_moved": FUNDS_MOVED,\n            "portfolio_mutated": PORTFOLIO_MUTATED,\n        }\n\n        receipt = LiveAcquisitionLineageCycleReceipt(\n            schema_version=SCHEMA_VERSION,\n            engine_id=ENGINE_ID,\n            receipt_type=RECEIPT_TYPE,\n            acquisition_batch_id=acquisition_batch_id,\n            cycle_observed_at=cycle_time.isoformat(),\n            cohort_observation_count=len(normalized_observations),\n            cohort_market_count=batch_receipt.batch_market_count,\n            transition_count=batch_receipt.transition_count,\n            ledger_market_count_before=(\n                batch_receipt.ledger_market_count_before\n            ),\n            ledger_record_count_before=(\n                batch_receipt.ledger_record_count_before\n            ),\n            ledger_market_count_after=(\n                batch_receipt.ledger_market_count_after\n            ),\n            ledger_record_count_after=(\n                batch_receipt.ledger_record_count_after\n            ),\n            lineage_batch_receipt=batch_receipt,\n            read_only=READ_ONLY,\n            execution_allowed=EXECUTION_ALLOWED,\n            execution_adapter_resolved=EXECUTION_ADAPTER_RESOLVED,\n            execution_adapter_invoked=EXECUTION_ADAPTER_INVOKED,\n            trade_authorization_allowed=TRADE_AUTHORIZATION_ALLOWED,\n            order_placement_allowed=ORDER_PLACEMENT_ALLOWED,\n            funds_moved=FUNDS_MOVED,\n            portfolio_mutated=PORTFOLIO_MUTATED,\n            cycle_receipt_hash=_stable_hash(payload),\n        )\n\n        receipt.assert_invariants()\n        return receipt\n'

TEST_SOURCE = 'from datetime import datetime, timezone\n\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_live_acquisition_lineage_cycle_bridge import (\n    LiveAcquisitionLineageCycleContractError,\n    OracleLiveAcquisitionLineageCycleBridge,\n)\nfrom qseries_v2.oracle_intelligence.live_acquisition.oracle_live_read_only_acquisition_runtime import (\n    CanonicalObservation,\n    RawSourceObservation,\n)\n\n\nT1 = datetime(2026, 7, 14, 9, 0, 0, tzinfo=timezone.utc)\nT2 = datetime(2026, 7, 14, 9, 0, 15, tzinfo=timezone.utc)\nT3 = datetime(2026, 7, 14, 9, 0, 30, tzinfo=timezone.utc)\n\n\ndef build_observation(\n    *,\n    market_id,\n    frame_id,\n    acquisition_batch_id,\n    yes_ask="0.6140",\n):\n    payload = {\n        "source_market_id": market_id,\n        "yes_bid_dollars": "0.0000",\n        "yes_bid_size_fp": "0.00",\n        "yes_ask_dollars": yes_ask,\n        "yes_ask_size_fp": "40.00",\n        "no_bid_dollars": "0.3860",\n        "no_ask_dollars": "0.0000",\n        "last_price_dollars": "0.0000",\n        "previous_yes_bid_dollars": "0.0000",\n        "previous_yes_ask_dollars": "0.6000",\n        "previous_price_dollars": "0.0000",\n        "volume_fp": "0.00",\n        "volume_24h_fp": "0.00",\n        "open_interest_fp": "0.00",\n        "liquidity_dollars": "0.0000",\n    }\n\n    raw = RawSourceObservation.create(\n        source_observation_id=(\n            "kalshi." + market_id + "." + frame_id\n        ),\n        observed_at=T1,\n        observation_type="market_snapshot",\n        payload=payload,\n        provenance={\n            "source_id": "source.kalshi.market_data",\n            "frame_id": frame_id,\n        },\n    )\n\n    return CanonicalObservation.create(\n        source_id="source.kalshi.market_data",\n        raw_observation=raw,\n        acquired_at=T1,\n        acquisition_batch_id=acquisition_batch_id,\n    )\n\n\ndef build_cycle(\n    *,\n    cycle_number,\n    changed_market=None,\n):\n    batch_id = f"batch.ola.036.cycle.{cycle_number}"\n    observations = []\n\n    for index in range(1, 6):\n        market_id = f"KXTEST-LIVE-CYCLE-{index}"\n        yes_ask = (\n            "0.8800"\n            if changed_market == market_id\n            else "0.6140"\n        )\n\n        observations.append(\n            build_observation(\n                market_id=market_id,\n                frame_id=f"{cycle_number}-{index}",\n                acquisition_batch_id=batch_id,\n                yes_ask=yes_ask,\n            )\n        )\n\n    return tuple(observations)\n\n\ndef run_first_cycle_test():\n    bridge = OracleLiveAcquisitionLineageCycleBridge()\n\n    receipt = bridge.advance_cycle(\n        observations=build_cycle(cycle_number=1),\n        cycle_observed_at=T1,\n    )\n\n    assert receipt.acquisition_batch_id == "batch.ola.036.cycle.1"\n    assert receipt.cohort_observation_count == 5\n    assert receipt.cohort_market_count == 5\n    assert receipt.transition_count == 0\n    assert receipt.ledger_market_count_before == 0\n    assert receipt.ledger_record_count_before == 0\n    assert receipt.ledger_market_count_after == 5\n    assert receipt.ledger_record_count_after == 5\n\n    return bridge, receipt\n\n\ndef run_repeated_same_cycle_cohort_test():\n    bridge, _ = run_first_cycle_test()\n\n    second = bridge.advance_cycle(\n        observations=build_cycle(cycle_number=2),\n        cycle_observed_at=T2,\n    )\n\n    assert second.transition_count == 0\n    assert second.ledger_market_count_after == 5\n    assert second.ledger_record_count_after == 10\n\n    for item in second.lineage_batch_receipt.receipts:\n        assert item.consecutive_frame_count == 2\n        assert item.dwell_seconds == "15.000000"\n\n    return bridge, second\n\n\ndef run_real_change_cycle_test():\n    bridge, _ = run_repeated_same_cycle_cohort_test()\n\n    third = bridge.advance_cycle(\n        observations=build_cycle(\n            cycle_number=3,\n            changed_market="KXTEST-LIVE-CYCLE-4",\n        ),\n        cycle_observed_at=T3,\n    )\n\n    assert third.transition_count == 1\n    assert third.ledger_record_count_after == 15\n\n    changed = [\n        item\n        for item in third.lineage_batch_receipt.receipts\n        if item.transition_detected\n    ]\n\n    assert len(changed) == 1\n    assert changed[0].source_market_id == "KXTEST-LIVE-CYCLE-4"\n    assert changed[0].consecutive_frame_count == 1\n    assert changed[0].dwell_seconds == "0.000000"\n    assert changed[0].state_changed_at == T3.isoformat()\n\n    unchanged = [\n        item\n        for item in third.lineage_batch_receipt.receipts\n        if not item.transition_detected\n    ]\n\n    assert len(unchanged) == 4\n\n    for item in unchanged:\n        assert item.consecutive_frame_count == 3\n        assert item.dwell_seconds == "30.000000"\n\n    return third\n\n\ndef run_mixed_batch_identity_fail_closed_test():\n    bridge = OracleLiveAcquisitionLineageCycleBridge()\n\n    observations = list(build_cycle(cycle_number=1))\n\n    observations[-1] = build_observation(\n        market_id="KXTEST-LIVE-CYCLE-5",\n        frame_id="mixed-batch",\n        acquisition_batch_id="batch.ola.036.other",\n    )\n\n    try:\n        bridge.advance_cycle(\n            observations=observations,\n            cycle_observed_at=T1,\n        )\n        raise AssertionError(\n            "mixed acquisition batch identity must fail closed"\n        )\n    except LiveAcquisitionLineageCycleContractError:\n        pass\n\n    assert bridge.batch_router.bridge.ledger.record_count == 0\n\n\ndef run_naive_cycle_time_fail_closed_test():\n    bridge = OracleLiveAcquisitionLineageCycleBridge()\n\n    try:\n        bridge.advance_cycle(\n            observations=build_cycle(cycle_number=1),\n            cycle_observed_at=datetime(2026, 7, 14, 9, 0, 0),\n        )\n        raise AssertionError(\n            "naive cycle time must fail closed"\n        )\n    except LiveAcquisitionLineageCycleContractError:\n        pass\n\n    assert bridge.batch_router.bridge.ledger.record_count == 0\n\n\ndef run_deterministic_cycle_replay_test():\n    first = OracleLiveAcquisitionLineageCycleBridge()\n    second = OracleLiveAcquisitionLineageCycleBridge()\n\n    cycles = (\n        (build_cycle(cycle_number=1), T1),\n        (build_cycle(cycle_number=2), T2),\n        (\n            build_cycle(\n                cycle_number=3,\n                changed_market="KXTEST-LIVE-CYCLE-2",\n            ),\n            T3,\n        ),\n    )\n\n    first_receipts = []\n    second_receipts = []\n\n    for observations, observed_at in cycles:\n        first_receipts.append(\n            first.advance_cycle(\n                observations=observations,\n                cycle_observed_at=observed_at,\n            )\n        )\n        second_receipts.append(\n            second.advance_cycle(\n                observations=observations,\n                cycle_observed_at=observed_at,\n            )\n        )\n\n    assert first_receipts == second_receipts\n    assert (\n        first.batch_router.bridge.ledger.records()\n        == second.batch_router.bridge.ledger.records()\n    )\n\n    return first_receipts\n\n\ndef main():\n    _, first = run_first_cycle_test()\n    _, second = run_repeated_same_cycle_cohort_test()\n    third = run_real_change_cycle_test()\n\n    run_mixed_batch_identity_fail_closed_test()\n    run_naive_cycle_time_fail_closed_test()\n\n    replayed = run_deterministic_cycle_replay_test()\n\n    result = {\n        "schema_version": third.schema_version,\n        "engine_id": third.engine_id,\n        "status": "passed",\n        "canonical_live_cycle_consumed": True,\n        "shared_acquisition_batch_identity_enforced": True,\n        "cycle_time_bound_to_all_lineage_frames": True,\n        "ola_035_atomic_batch_router_consumed": True,\n        "five_market_cycle_advanced": (\n            first.cohort_market_count == 5\n        ),\n        "same_five_markets_second_frame_preserved": (\n            second.ledger_record_count_after == 10\n        ),\n        "same_state_dwell_advanced_across_cycles": True,\n        "real_market_change_detected_in_cycle": (\n            third.transition_count == 1\n        ),\n        "unchanged_market_dwell_preserved": True,\n        "mixed_batch_identity_fails_closed": True,\n        "naive_cycle_time_fails_closed": True,\n        "deterministic_cycle_replay_valid": (\n            len(replayed) == 3\n        ),\n        "no_acquisition_owned": True,\n        "no_persistence_owned": True,\n        "no_intelligence_interpretation": True,\n        "no_signal_scoring": True,\n        "alerts_allowed": False,\n        "qseries_handoff_allowed": False,\n        "read_only": third.read_only,\n        "execution_allowed": third.execution_allowed,\n        "execution_adapter_resolved": (\n            third.execution_adapter_resolved\n        ),\n        "execution_adapter_invoked": (\n            third.execution_adapter_invoked\n        ),\n        "trade_authorization_allowed": (\n            third.trade_authorization_allowed\n        ),\n        "order_placement_allowed": (\n            third.order_placement_allowed\n        ),\n        "funds_moved": third.funds_moved,\n        "portfolio_mutated": third.portfolio_mutated,\n    }\n\n    print(\n        "[PASS] OLA-036 Oracle Live Acquisition "\n        "Lineage Cycle Bridge"\n    )\n    print(result)\n\n\nif __name__ == "__main__":\n    main()\n'


def write_full_replacement(path: Path, source: str) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(source, encoding="utf-8", newline="\n")
    print(f"[OK] FULL REPLACEMENT: {path}")


def main() -> None:
    print("========================================")
    print(" OLA-036 INSTALLER")
    print(" ORACLE LIVE ACQUISITION LINEAGE CYCLE")
    print("========================================")

    write_full_replacement(
        PRODUCTION_PATH,
        PRODUCTION_SOURCE,
    )
    write_full_replacement(
        TEST_PATH,
        TEST_SOURCE,
    )

    print()
    print(
        "[DONE] OLA-036 Oracle Live Acquisition "
        "Lineage Cycle Bridge installed"
    )
    print()
    print("Run:")
    print(
        "py test_ola_036_oracle_live_acquisition_"
        "lineage_cycle_bridge.py"
    )


if __name__ == "__main__":
    main()
